const bcrypt = require('bcryptjs');
const { getDatabase } = require('../db');

class User {
  static hashPassword(password) {
    const salt = bcrypt.genSaltSync(10);
    return bcrypt.hashSync(password, salt);
  }

  static comparePassword(password, hash) {
    if (!password || !hash) return false;
    return bcrypt.compareSync(password, hash);
  }

  static toDict(user) {
    if (!user) return null;
    return {
      id: user.id,
      username: user.username,
      email: user.email,
      created_at: user.created_at || null
    };
  }

  static create({ username, email, password }, db = getDatabase()) {
    const passwordHash = this.hashPassword(password);
    const stmt = db.prepare(`
      INSERT INTO users (username, email, password_hash)
      VALUES (?, ?, ?)
    `);
    const result = stmt.run(username, email, passwordHash);
    const id = result.lastInsertRowid;
    return this.findById(id, db);
  }

  static findById(id, db = getDatabase()) {
    const stmt = db.prepare('SELECT * FROM users WHERE id = ?');
    return stmt.get(id);
  }

  static findByEmail(email, db = getDatabase()) {
    const stmt = db.prepare('SELECT * FROM users WHERE LOWER(email) = LOWER(?)');
    return stmt.get(email);
  }

  static findByUsername(username, db = getDatabase()) {
    const stmt = db.prepare('SELECT * FROM users WHERE username = ?');
    return stmt.get(username);
  }

  static findByEmailOrUsername(email, username, db = getDatabase()) {
    const stmt = db.prepare('SELECT * FROM users WHERE LOWER(email) = LOWER(?) OR username = ?');
    return stmt.get(email, username);
  }
}

module.exports = User;

