const { getDatabase } = require('../db');

class Task {
  static toDict(task) {
    if (!task) return null;
    return {
      id: Number(task.id),
      user_id: Number(task.user_id),
      title: task.title,
      description: task.description || '',
      is_completed: Boolean(task.is_completed),
      created_at: task.created_at || null,
      updated_at: task.updated_at || null
    };
  }

  static create({ user_id, title, description = '' }, db = getDatabase()) {
    const stmt = db.prepare(`
      INSERT INTO tasks (user_id, title, description, is_completed)
      VALUES (?, ?, ?, 0)
    `);
    const result = stmt.run(user_id, title, description);
    const id = result.lastInsertRowid;
    return this.findById(id, user_id, db);
  }

  static findById(id, userId, db = getDatabase()) {
    const stmt = db.prepare('SELECT * FROM tasks WHERE id = ? AND user_id = ?');
    const row = stmt.get(id, userId);
    return row ? this.toDict(row) : null;
  }

  static findByUser(userId, filter = {}, db = getDatabase()) {
    let query = 'SELECT * FROM tasks WHERE user_id = ?';
    const params = [userId];

    if (filter.completed !== undefined && filter.completed !== null) {
      query += ' AND is_completed = ?';
      params.push(filter.completed ? 1 : 0);
    }

    query += ' ORDER BY created_at DESC, id DESC';
    const stmt = db.prepare(query);
    const rows = stmt.all(...params);
    return rows.map((r) => this.toDict(r));
  }

  static update(id, userId, fields = {}, db = getDatabase()) {
    const existing = this.findById(id, userId, db);
    if (!existing) return null;

    const updates = [];
    const params = [];

    if (fields.title !== undefined) {
      updates.push('title = ?');
      params.push(fields.title);
    }
    if (fields.description !== undefined) {
      updates.push('description = ?');
      params.push(fields.description);
    }
    if (fields.is_completed !== undefined) {
      updates.push('is_completed = ?');
      params.push(fields.is_completed ? 1 : 0);
    }

    updates.push("updated_at = datetime('now')");

    const query = `UPDATE tasks SET ${updates.join(', ')} WHERE id = ? AND user_id = ?`;
    params.push(id, userId);

    db.prepare(query).run(...params);
    return this.findById(id, userId, db);
  }

  static delete(id, userId, db = getDatabase()) {
    const existing = this.findById(id, userId, db);
    if (!existing) return false;

    const stmt = db.prepare('DELETE FROM tasks WHERE id = ? AND user_id = ?');
    stmt.run(id, userId);
    return true;
  }
}

module.exports = Task;
